<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { calculoLabels, cambiarEstadoConceptoPlanilla, guardarConceptoPlanilla, listarConceptosPlanilla, listarOpcionesConceptosPlanilla, naturalezaLabels, naturalezas, tiposCalculo } from '../services/conceptosPlanilla'
import type { ConceptoOption, ConceptoPlanilla, ConceptoPlanillaPayload } from '../interfaces/conceptosPlanilla.interface'
type EstadoFiltro='todos'|'activo'|'inactivo'; type NullableFilter=number|'todos'|'ninguno'
const rows=ref<ConceptoPlanilla[]>([]),tipos=ref<ConceptoOption[]>([]),regimenes=ref<ConceptoOption[]>([]),agrupadoras=ref<ConceptoOption[]>([]),criterio=ref(''),tipoFiltro=ref<number|'todos'>('todos'),regimenFiltro=ref<NullableFilter>('todos'),agrupadoraFiltro=ref<NullableFilter>('todos'),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const defaults:ConceptoPlanillaPayload={codigo:'',descripcion:'',tipo_concepto_id:0,regimen_id:null,agrupadora_concepto_id:null,naturaleza:'REMUNERATIVO',tipo_calculo:'MANUAL',valor_base:null,formula:null,orden_calculo:1};const form=reactive<ConceptoPlanillaPayload>({...defaults})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.';const formulaVisible=computed(()=>form.tipo_calculo==='FORMULA'||form.tipo_calculo==='DINAMICO')
const matchNullable=(value:number|null,filter:NullableFilter)=>filter==='todos'||(filter==='ninguno'?value===null:value===filter)
const filtered=computed(()=>{const q=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(x=>(!q||`${x.codigo} ${x.descripcion}`.toLocaleLowerCase().includes(q))&&(tipoFiltro.value==='todos'||x.tipo_concepto_id===tipoFiltro.value)&&matchNullable(x.regimen_id,regimenFiltro.value)&&matchNullable(x.agrupadora_concepto_id,agrupadoraFiltro.value)&&(estadoFiltro.value==='todos'||x.estado===(estadoFiltro.value==='activo')))})
async function load(){loading.value=true;error.value='';try{const [items,opts]=await Promise.all([listarConceptosPlanilla(),listarOpcionesConceptosPlanilla()]);rows.value=items;tipos.value=opts.tipos_concepto;regimenes.value=opts.regimenes;agrupadoras.value=opts.agrupadoras}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:ConceptoPlanilla){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,descripcion:item.descripcion,tipo_concepto_id:item.tipo_concepto_id,regimen_id:item.regimen_id,agrupadora_concepto_id:item.agrupadora_concepto_id,naturaleza:item.naturaleza,tipo_calculo:item.tipo_calculo,valor_base:item.valor_base===null?null:Number(item.valor_base),formula:item.formula,orden_calculo:item.orden_calculo}:{...defaults});error.value='';modal.value=true}
function validate(){if(form.codigo.trim().length<2||form.codigo.trim().length>20)return 'El código debe tener entre 2 y 20 caracteres.';if(form.descripcion.trim().length<3||form.descripcion.trim().length>200)return 'La descripción debe tener entre 3 y 200 caracteres.';if(!form.tipo_concepto_id)return 'Debe seleccionar el tipo de concepto.';if(form.valor_base!==null&&(!Number.isFinite(form.valor_base)||form.valor_base<0||form.valor_base>999999.99))return 'El valor base debe estar entre 0 y 999,999.99.';if(!Number.isInteger(form.orden_calculo)||form.orden_calculo<1||form.orden_calculo>999)return 'El orden de cálculo debe ser un entero entre 1 y 999.';if(formulaVisible.value&&!form.formula?.trim())return 'La fórmula es obligatoria para el tipo de cálculo seleccionado.';if((form.formula??'').length>1000)return 'La fórmula admite como máximo 1000 caracteres.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarConceptoPlanilla(editing.value,{...form,codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim().toUpperCase(),formula:formulaVisible.value?(form.formula?.trim().toUpperCase()??null):null});modal.value=false;success.value=`Concepto ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:ConceptoPlanilla){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el concepto ${item.descripcion}?`))return;try{const r=await cambiarEstadoConceptoPlanilla(item.id);item.estado=r.estado;success.value=r.message??`Concepto ${item.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
function clearFilters(){criterio.value='';tipoFiltro.value='todos';regimenFiltro.value='todos';agrupadoraFiltro.value='todos';estadoFiltro.value='todos'}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Conceptos de planilla</nav><header class="hero"><div class="mark">CP</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Conceptos de planilla</h1><p>Reglas, fórmulas y orden de cálculo para remuneraciones y descuentos.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Nuevo concepto</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Código o descripción"></label><label>Tipo<select v-model="tipoFiltro"><option value="todos">Todos</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Régimen<select v-model="regimenFiltro"><option value="todos">Todos</option><option value="ninguno">Sin régimen</option><option v-for="x in regimenes" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Agrupadora<select v-model="agrupadoraFiltro"><option value="todos">Todas</option><option value="ninguno">Sin agrupadora</option><option v-for="x in agrupadoras" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activos</option><option value="inactivo">Inactivos</option></select></label><button class="soft" @click="clearFilters">Limpiar</button></section><section class="table-card"><header><small>MOTOR DE CÁLCULO</small><h2>Conceptos registrados</h2></header><div v-if="loading" class="empty">Consultando conceptos…</div><div v-else-if="!filtered.length" class="empty">No se encontraron conceptos.</div><div v-else class="scroll"><table><thead><tr><th>Orden</th><th>Código / descripción</th><th>Tipo</th><th>Régimen</th><th>Agrupadora</th><th>Naturaleza</th><th>Cálculo</th><th>Valor base</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td><span class="order">{{x.orden_calculo}}</span></td><td><b>{{x.codigo}}</b><small>{{x.descripcion}}</small></td><td>{{x.tipo_concepto?.descripcion??'—'}}</td><td>{{x.regimen?.descripcion??'TODOS'}}</td><td>{{x.agrupadora_concepto?.descripcion??'—'}}</td><td><span class="nature" :data-nature="x.naturaleza">{{naturalezaLabels[x.naturaleza]}}</span></td><td><span class="calc">{{calculoLabels[x.tipo_calculo]}}</span></td><td>{{x.valor_base===null?'—':Number(x.valor_base).toFixed(2)}}</td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">CP</div><div><small>MOTOR DE CÁLCULO</small><h2>{{editing?'Editar':'Registrar'}} concepto</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="20" @input="form.codigo=form.codigo.toUpperCase()"></label><label class="wide">Descripción *<input v-model="form.descripcion" maxlength="200" @input="form.descripcion=form.descripcion.toUpperCase()"></label><h3>Clasificación</h3><label>Tipo de concepto *<select v-model="form.tipo_concepto_id"><option :value="0">Seleccione</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}}</option></select></label><label>Régimen<select v-model="form.regimen_id"><option :value="null">TODOS / SIN RÉGIMEN</option><option v-for="x in regimenes" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}}</option></select></label><label>Agrupadora<select v-model="form.agrupadora_concepto_id"><option :value="null">SIN AGRUPADORA</option><option v-for="x in agrupadoras" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}}</option></select></label><label>Naturaleza *<select v-model="form.naturaleza"><option v-for="x in naturalezas" :key="x" :value="x">{{naturalezaLabels[x]}}</option></select></label><h3>Cálculo</h3><label>Tipo de cálculo *<select v-model="form.tipo_calculo"><option v-for="x in tiposCalculo" :key="x" :value="x">{{calculoLabels[x]}}</option></select></label><label>Valor base<input v-model.number="form.valor_base" type="number" min="0" max="999999.99" step="0.01" :placeholder="form.tipo_calculo==='FIJO'?'Monto fijo en soles':form.tipo_calculo==='PORCENTAJE'?'Porcentaje base':'0.00'"></label><label>Orden de cálculo *<input v-model.number="form.orden_calculo" type="number" min="1" max="999" step="1"></label><label v-if="formulaVisible" class="full">Fórmula *<textarea v-model="form.formula" maxlength="1000" rows="3" placeholder="Ej. (SUELDO_BASICO * 0.12) + BONIFICACION_FAMILIAR" @input="form.formula=form.formula?.toUpperCase()??null"></textarea><small>{{form.formula?.length??0}} / 1000 caracteres</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#3d6fb4;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.62rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#ebf2fc;font-size:.52rem}.hero button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:12px;display:flex;align-items:end;gap:5px;border-radius:9px;background:#fff}.filters label{min-width:120px;font-size:.48rem}.filters label:first-child{margin-right:auto}.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{width:100%;box-sizing:border-box;margin-top:4px;padding:7px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.5rem}.soft{padding:8px;border:0;border-radius:6px;color:#64727a;background:#edf1f3;font-size:.5rem}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.48rem}th,td{padding:8px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}td>b,td>small{display:block}.active,.inactive,.nature,.calc,.order{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.4rem}.active,.nature[data-nature=REMUNERATIVO]{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.nature[data-nature=NO_REMUNERATIVO]{color:#89600d;background:#fff1d0}.nature[data-nature=INFORMATIVO],.calc{color:#315d92;background:#eaf3fb}.order{color:#fff;background:#59666c}.actions{display:flex;gap:4px}.actions button{padding:5px 7px;border:0;border-radius:5px;font-size:.44rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:92vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:7px;font-size:.48rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.wide{grid-column:span 2}.full,.grid h3{grid-column:1/-1}.grid h3{margin:12px 0 0;padding-bottom:5px;border-bottom:1px solid #e8ecee;font-size:.58rem}.dialog label small{margin-top:4px;color:#7e8a90}.dialog>footer{margin-top:15px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:800px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.wide,.full,.grid h3{grid-column:auto}.actions{min-width:135px}}
</style>
